-- =============================================================
-- 0001_schema.sql
-- =============================================================
-- 古問 LORE — schema
-- Run in the Supabase SQL editor (or `supabase db push`), before 0002_rls.sql.

-- ─────────────────────────────────────────────────────────────
-- Users
-- ─────────────────────────────────────────────────────────────

create table public.profiles (
  id          uuid primary key references auth.users (id) on delete cascade,
  nickname    text not null check (char_length(nickname) between 1 and 30),
  language    text not null default 'zh-HK' check (language in ('zh-HK', 'en')),
  is_admin    boolean not null default false,
  created_at  timestamptz not null default now()
);

-- Emails that become admins on sign-up. Filled by `npm run seed` from ADMIN_EMAILS.
create table public.admin_emails (
  email text primary key check (email = lower(email))
);

-- ─────────────────────────────────────────────────────────────
-- Content
-- ─────────────────────────────────────────────────────────────

create table public.classics (
  id              uuid primary key default gen_random_uuid(),
  slug            text not null unique check (slug ~ '^[a-z0-9-]+$'),
  title_zh        text not null,
  title_en        text not null,
  author_zh       text not null,
  author_en       text not null,
  era_zh          text,
  era_en          text,
  description_zh  text,
  description_en  text,
  created_at      timestamptz not null default now()
);

create table public.excerpts (
  id                  uuid primary key default gen_random_uuid(),
  classic_id          uuid not null references public.classics (id) on delete cascade,
  -- Paragraphs are separated by a blank line.
  text_zh             text,
  text_en             text,
  -- true when text_zh is an original summary rather than a translation.
  text_zh_is_summary  boolean not null default false,
  source_note         text not null,
  translator          text,
  created_at          timestamptz not null default now()
);

create table public.questions (
  id           uuid primary key default gen_random_uuid(),
  slug         text not null unique check (slug ~ '^[a-z0-9-]+$'),
  question_zh  text not null,
  question_en  text not null,
  tags         text[] not null default '{}',
  difficulty   smallint not null default 1 check (difficulty between 1 and 3),
  excerpt_id   uuid references public.excerpts (id) on delete set null,
  status       text not null default 'draft' check (status in ('draft', 'published', 'archived')),
  featured     boolean not null default false,
  created_at   timestamptz not null default now()
);

-- ─────────────────────────────────────────────────────────────
-- Community
-- ─────────────────────────────────────────────────────────────

create table public.reflections (
  id              uuid primary key default gen_random_uuid(),
  question_id     uuid not null references public.questions (id) on delete cascade,
  user_id         uuid not null references public.profiles (id) on delete cascade,
  initial_answer  text check (char_length(initial_answer) <= 500),
  body            text not null default '' check (char_length(body) <= 1500),
  is_anonymous    boolean not null default false,
  -- draft → published (by the author); published ⇄ hidden (by an admin)
  status          text not null default 'draft' check (status in ('draft', 'published', 'hidden')),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  submitted_at    timestamptz,
  unique (question_id, user_id),
  constraint reflection_min_length check (status = 'draft' or char_length(btrim(body)) >= 50)
);

create table public.comments (
  id             uuid primary key default gen_random_uuid(),
  reflection_id  uuid not null references public.reflections (id) on delete cascade,
  user_id        uuid not null references public.profiles (id) on delete cascade,
  parent_id      uuid references public.comments (id) on delete cascade,
  body           text not null check (char_length(btrim(body)) between 1 and 1000),
  status         text not null default 'visible' check (status in ('visible', 'hidden')),
  created_at     timestamptz not null default now()
);

create table public.likes (
  user_id        uuid not null references public.profiles (id) on delete cascade,
  reflection_id  uuid not null references public.reflections (id) on delete cascade,
  created_at     timestamptz not null default now(),
  primary key (user_id, reflection_id)
);

create table public.reports (
  id           uuid primary key default gen_random_uuid(),
  target_type  text not null check (target_type in ('reflection', 'comment')),
  target_id    uuid not null,
  reporter_id  uuid not null references public.profiles (id) on delete cascade,
  reason       text not null check (char_length(btrim(reason)) between 1 and 500),
  status       text not null default 'open' check (status in ('open', 'resolved')),
  created_at   timestamptz not null default now(),
  unique (target_type, target_id, reporter_id)
);

-- ─────────────────────────────────────────────────────────────
-- AI
-- ─────────────────────────────────────────────────────────────

-- One row per AI Companion call. Counts only — no message content.
create table public.ai_messages_usage (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.profiles (id) on delete cascade,
  question_id  uuid references public.questions (id) on delete set null,
  created_at   timestamptz not null default now()
);

-- Cached community summaries; the newest row per question is shown.
create table public.ai_insights (
  id            uuid primary key default gen_random_uuid(),
  question_id   uuid not null references public.questions (id) on delete cascade,
  summary_json  jsonb not null,
  generated_at  timestamptz not null default now()
);

-- ─────────────────────────────────────────────────────────────
-- Analytics
-- ─────────────────────────────────────────────────────────────

create table public.events (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid references public.profiles (id) on delete set null,
  -- Random per-browser id so signed-out visitors can be counted.
  anon_id      text check (char_length(anon_id) <= 64),
  question_id  uuid references public.questions (id) on delete cascade,
  type         text not null check (type in (
                 'view_question', 'open_text', 'finish_text', 'ask_ai',
                 'submit_reflection', 'unlock', 'comment')),
  created_at   timestamptz not null default now()
);

create table public.feedback (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid references public.profiles (id) on delete set null,
  question_id   uuid references public.questions (id) on delete cascade,
  rating        smallint not null check (rating between 1 and 5),
  ai_helped     smallint check (ai_helped between 1 and 5),
  own_view      smallint check (own_view between 1 and 5),
  comment       text check (char_length(comment) <= 500),
  created_at    timestamptz not null default now()
);

-- ─────────────────────────────────────────────────────────────
-- Indexes
-- ─────────────────────────────────────────────────────────────

create index on public.excerpts (classic_id);
create index on public.questions (status);
create index on public.reflections (question_id, status);
create index on public.comments (reflection_id);
create index on public.likes (reflection_id);
create index on public.ai_messages_usage (user_id, created_at);
create index on public.ai_insights (question_id, generated_at desc);
create index on public.events (question_id, type);
create index on public.events (created_at);
create index on public.reports (status);


-- =============================================================
-- 0002_rls.sql
-- =============================================================
-- 古問 LORE — functions, triggers, privileges and Row Level Security
-- Run after 0001_schema.sql.
--
-- THE UNLOCK RULE
--   Nobody can read another user's reflection (or the comments, likes and
--   AI insight under it) for a question until they have submitted their own
--   reflection for that same question.
--
--   How it is enforced:
--   * `reflections`, `comments` and `likes` tables: a user can only SELECT
--     their own rows (admins: all). There is no path to other people's rows
--     through the table API at all.
--   * Other people's content is served only by the SECURITY DEFINER
--     functions `reflection_feed()` and `comment_feed()`, which return
--     nothing unless `has_reflected(question)` is true for the caller.
--     They also strip the author's identity from anonymous reflections,
--     which plain RLS cannot do (RLS filters rows, not columns).
--   * Writing a comment or like also requires `has_reflected`.

-- ─────────────────────────────────────────────────────────────
-- Helper functions
-- ─────────────────────────────────────────────────────────────

create or replace function public.is_admin()
returns boolean
language sql stable security definer set search_path = ''
as $$
  select coalesce(
    (select p.is_admin from public.profiles p where p.id = auth.uid()),
    false);
$$;

-- True once the caller has submitted (not merely drafted) a reflection
-- for the question. A reflection later hidden by a moderator still counts.
create or replace function public.has_reflected(p_question uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.reflections r
    where r.question_id = p_question
      and r.user_id = auth.uid()
      and r.status in ('published', 'hidden'));
$$;

create or replace function public.question_of_reflection(p_reflection uuid)
returns uuid
language sql stable security definer set search_path = ''
as $$
  select r.question_id from public.reflections r where r.id = p_reflection;
$$;

create or replace function public.reflection_is_published(p_reflection uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.reflections r
    where r.id = p_reflection and r.status = 'published');
$$;

-- ─────────────────────────────────────────────────────────────
-- New user → profile
-- ─────────────────────────────────────────────────────────────

create or replace function public.handle_new_user()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  insert into public.profiles (id, nickname, is_admin)
  values (
    new.id,
    '讀者' || lpad(floor(random() * 10000)::int::text, 4, '0'),
    exists (select 1 from public.admin_emails a where a.email = lower(new.email)));
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ─────────────────────────────────────────────────────────────
-- Write guards
-- ─────────────────────────────────────────────────────────────
-- "privileged" = an admin, or a connection with no user (the service-role
-- key or the SQL editor). Everyone else gets the restricted rules below.

create or replace function public.reflections_guard()
returns trigger
language plpgsql set search_path = ''
as $$
declare
  privileged boolean := auth.uid() is null or public.is_admin();
begin
  new.updated_at := now();

  if tg_op = 'UPDATE' then
    if new.user_id <> old.user_id or new.question_id <> old.question_id then
      raise exception 'A reflection cannot change owner or question';
    end if;
    new.created_at := old.created_at;
  end if;

  if not privileged then
    if tg_op = 'UPDATE' and old.status = 'hidden' then
      raise exception 'This reflection has been hidden by a moderator';
    end if;
    if new.status = 'hidden' then
      raise exception 'Only moderators can hide reflections';
    end if;
    if tg_op = 'UPDATE' and old.status = 'published' and new.status = 'draft' then
      raise exception 'A submitted reflection cannot go back to draft';
    end if;
    new.submitted_at := case
      when tg_op = 'UPDATE' and old.submitted_at is not null then old.submitted_at
      when new.status = 'published' then now()
      else null
    end;
  elsif new.status <> 'draft' and new.submitted_at is null then
    new.submitted_at := now();
  end if;

  return new;
end;
$$;

create trigger reflections_guard
  before insert or update on public.reflections
  for each row execute function public.reflections_guard();

create or replace function public.comments_guard()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  privileged boolean := auth.uid() is null or public.is_admin();
  parent_reflection uuid;
  grandparent uuid;
begin
  if tg_op = 'UPDATE' then
    -- Only moderation status may change.
    new.reflection_id := old.reflection_id;
    new.user_id := old.user_id;
    new.parent_id := old.parent_id;
    new.body := old.body;
    new.created_at := old.created_at;
    return new;
  end if;

  if new.parent_id is not null then
    select c.reflection_id, c.parent_id into parent_reflection, grandparent
    from public.comments c where c.id = new.parent_id;
    if parent_reflection is distinct from new.reflection_id then
      raise exception 'A reply must belong to the same reflection as its parent';
    end if;
    if grandparent is not null then
      raise exception 'Replies can only be nested one level deep';
    end if;
  end if;

  if not privileged then
    new.status := 'visible';
    new.created_at := now();
    if (select count(*) from public.comments c
        where c.user_id = new.user_id
          and c.created_at > now() - interval '10 minutes') >= 10 then
      raise exception 'Too many comments — please wait a few minutes';
    end if;
  end if;

  return new;
end;
$$;

create trigger comments_guard
  before insert or update on public.comments
  for each row execute function public.comments_guard();

-- ─────────────────────────────────────────────────────────────
-- Read functions (the only way to see other people's content)
-- ─────────────────────────────────────────────────────────────

create or replace function public.reflection_feed(p_question uuid)
returns table (
  id             uuid,
  body           text,
  is_anonymous   boolean,
  nickname       text,
  submitted_at   timestamptz,
  like_count     bigint,
  comment_count  bigint,
  liked_by_me    boolean,
  is_mine        boolean
)
language sql stable security definer set search_path = ''
as $$
  select
    r.id,
    r.body,
    r.is_anonymous,
    case when r.is_anonymous then null else p.nickname end,
    r.submitted_at,
    (select count(*) from public.likes l where l.reflection_id = r.id),
    (select count(*) from public.comments c
       where c.reflection_id = r.id and c.status = 'visible'),
    exists (select 1 from public.likes l
              where l.reflection_id = r.id and l.user_id = auth.uid()),
    coalesce(r.user_id = auth.uid(), false)
  from public.reflections r
  join public.profiles p on p.id = r.user_id
  where r.question_id = p_question
    and r.status = 'published'
    and public.has_reflected(p_question)
  order by r.submitted_at desc;
$$;

create or replace function public.comment_feed(p_question uuid)
returns table (
  id             uuid,
  reflection_id  uuid,
  parent_id      uuid,
  body           text,
  nickname       text,
  -- true when the comment is by the reflection's author
  is_author      boolean,
  created_at     timestamptz,
  is_mine        boolean
)
language sql stable security definer set search_path = ''
as $$
  select
    c.id,
    c.reflection_id,
    c.parent_id,
    c.body,
    -- An anonymous author replying in their own thread stays anonymous.
    case when c.user_id = r.user_id and r.is_anonymous then null else p.nickname end,
    c.user_id = r.user_id,
    c.created_at,
    coalesce(c.user_id = auth.uid(), false)
  from public.comments c
  join public.reflections r on r.id = c.reflection_id
  join public.profiles p on p.id = c.user_id
  where r.question_id = p_question
    and r.status = 'published'
    and c.status = 'visible'
    and public.has_reflected(p_question)
  order by c.created_at;
$$;

-- Public, aggregate only: how many people opened each question's text.
create or replace function public.question_reader_counts()
returns table (question_id uuid, readers bigint)
language sql stable security definer set search_path = ''
as $$
  select e.question_id, count(distinct coalesce(e.user_id::text, e.anon_id))
  from public.events e
  where e.type = 'open_text' and e.question_id is not null
  group by e.question_id;
$$;

-- ─────────────────────────────────────────────────────────────
-- Privileges
-- ─────────────────────────────────────────────────────────────
-- Supabase grants everything to anon/authenticated by default and relies on
-- RLS alone. We start from nothing and grant only what the app needs.

revoke all on all tables in schema public from anon, authenticated;
revoke all on all functions in schema public from public, anon, authenticated;

grant usage on schema public to anon, authenticated;

-- The service role is the server's privileged connection: seeding, the AI
-- Insight job and account deletion. It bypasses RLS, but it still needs
-- ordinary table privileges. Supabase usually grants these by default; we
-- make it explicit so a project created by a different role still works.
grant usage on schema public to service_role;
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;
grant all on all functions in schema public to service_role;
alter default privileges in schema public grant all on tables to service_role;
alter default privileges in schema public grant all on sequences to service_role;
alter default privileges in schema public grant execute on functions to service_role;

grant select on public.classics, public.excerpts, public.questions to anon, authenticated;
grant insert, update, delete on public.classics, public.excerpts, public.questions to authenticated;

grant select, delete on public.profiles to authenticated;
grant update (nickname, language) on public.profiles to authenticated;

grant select, insert, update, delete on public.reflections to authenticated;
grant select, insert, update, delete on public.comments to authenticated;
grant select, insert, delete on public.likes to authenticated;
grant select, insert, update on public.reports to authenticated;
grant select, insert on public.ai_messages_usage to authenticated;
grant select, insert, delete on public.ai_insights to authenticated;
grant insert on public.events to anon, authenticated;
grant select on public.events to authenticated;
grant insert on public.feedback to authenticated;
grant select on public.feedback to authenticated;

grant execute on function
  public.is_admin(),
  public.has_reflected(uuid),
  public.question_of_reflection(uuid),
  public.reflection_is_published(uuid),
  public.reflection_feed(uuid),
  public.comment_feed(uuid),
  public.question_reader_counts()
to anon, authenticated;

-- ─────────────────────────────────────────────────────────────
-- Row Level Security
-- ─────────────────────────────────────────────────────────────

alter table public.profiles          enable row level security;
alter table public.admin_emails      enable row level security;
alter table public.classics          enable row level security;
alter table public.excerpts          enable row level security;
alter table public.questions         enable row level security;
alter table public.reflections       enable row level security;
alter table public.comments          enable row level security;
alter table public.likes             enable row level security;
alter table public.reports           enable row level security;
alter table public.ai_messages_usage enable row level security;
alter table public.ai_insights       enable row level security;
alter table public.events            enable row level security;
alter table public.feedback          enable row level security;

-- profiles
create policy "read own profile" on public.profiles
  for select using (id = auth.uid() or public.is_admin());
create policy "update own profile" on public.profiles
  for update using (id = auth.uid()) with check (id = auth.uid());
create policy "delete own profile" on public.profiles
  for delete using (id = auth.uid());

-- admin_emails: no policies → service role only.

-- content: public read, admin write
create policy "read classics" on public.classics for select using (true);
create policy "admin writes classics" on public.classics
  for all using (public.is_admin()) with check (public.is_admin());

create policy "read excerpts" on public.excerpts for select using (true);
create policy "admin writes excerpts" on public.excerpts
  for all using (public.is_admin()) with check (public.is_admin());

create policy "read published questions" on public.questions
  for select using (status = 'published' or public.is_admin());
create policy "admin writes questions" on public.questions
  for all using (public.is_admin()) with check (public.is_admin());

-- reflections: own rows only (others via reflection_feed)
create policy "read own reflections" on public.reflections
  for select using (user_id = auth.uid() or public.is_admin());
create policy "write own reflection" on public.reflections
  for insert with check (
    user_id = auth.uid()
    and exists (select 1 from public.questions q
                where q.id = question_id and q.status = 'published'));
create policy "update own reflection" on public.reflections
  for update using (user_id = auth.uid() or public.is_admin())
  with check (user_id = auth.uid() or public.is_admin());
create policy "delete own reflection" on public.reflections
  for delete using (user_id = auth.uid() or public.is_admin());

-- comments: own rows only (others via comment_feed); writing needs unlock
create policy "read own comments" on public.comments
  for select using (user_id = auth.uid() or public.is_admin());
create policy "comment after unlocking" on public.comments
  for insert with check (
    user_id = auth.uid()
    and public.reflection_is_published(reflection_id)
    and public.has_reflected(public.question_of_reflection(reflection_id)));
create policy "admin moderates comments" on public.comments
  for update using (public.is_admin()) with check (public.is_admin());
create policy "delete own comment" on public.comments
  for delete using (user_id = auth.uid() or public.is_admin());

-- likes
create policy "read own likes" on public.likes
  for select using (user_id = auth.uid());
create policy "like after unlocking" on public.likes
  for insert with check (
    user_id = auth.uid()
    and public.reflection_is_published(reflection_id)
    and public.has_reflected(public.question_of_reflection(reflection_id)));
create policy "unlike" on public.likes
  for delete using (user_id = auth.uid());

-- reports
create policy "file a report" on public.reports
  for insert with check (reporter_id = auth.uid());
create policy "admin reads reports" on public.reports
  for select using (public.is_admin());
create policy "admin resolves reports" on public.reports
  for update using (public.is_admin()) with check (public.is_admin());

-- AI usage counter
create policy "read own ai usage" on public.ai_messages_usage
  for select using (user_id = auth.uid() or public.is_admin());
create policy "log own ai usage" on public.ai_messages_usage
  for insert with check (user_id = auth.uid());

-- AI insights: behind the same unlock as reflections
create policy "read insight after unlocking" on public.ai_insights
  for select using (public.has_reflected(question_id) or public.is_admin());
create policy "admin writes insights" on public.ai_insights
  for insert with check (public.is_admin());
create policy "admin deletes insights" on public.ai_insights
  for delete using (public.is_admin());

-- events: anyone may log their own; only admins read
create policy "log own events" on public.events
  for insert with check (user_id is null or user_id = auth.uid());
create policy "admin reads events" on public.events
  for select using (public.is_admin());

-- feedback
create policy "give feedback" on public.feedback
  for insert with check (user_id = auth.uid());
create policy "admin reads feedback" on public.feedback
  for select using (public.is_admin());


-- =============================================================
-- 0003_admin_analytics.sql
-- =============================================================
-- 古問 LORE — feedback rules and admin analytics
-- Run after 0002_rls.sql.

-- ─────────────────────────────────────────────────────────────
-- Feedback: one per reader per question; readers can see their own
-- (so the form isn't shown twice).
-- ─────────────────────────────────────────────────────────────

alter table public.feedback
  add constraint feedback_one_per_question unique (user_id, question_id);

create policy "read own feedback" on public.feedback
  for select using (user_id = auth.uid());

-- ─────────────────────────────────────────────────────────────
-- Analytics for the admin dashboard and grant report.
--
-- One row per question, plus a total row where question_id is null.
-- Each column counts distinct people (signed-in user, or a signed-out
-- browser's anon_id) who did that thing at least once.
-- ─────────────────────────────────────────────────────────────

create or replace function public.admin_analytics()
returns table (
  question_id     uuid,
  visitors        bigint,
  opened_text     bigint,
  finished_text   bigint,
  asked_ai        bigint,
  reflected       bigint,
  unlocked        bigint,
  commented       bigint,
  feedback_count  bigint,
  avg_rating      numeric,
  avg_ai_helped   numeric,
  avg_own_view    numeric
)
language plpgsql stable security definer set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;

  return query
  with actors as (
    select e.question_id as qid, e.type, coalesce(e.user_id::text, e.anon_id) as actor
    from public.events e
    where e.question_id is not null
      and coalesce(e.user_id::text, e.anon_id) is not null
  ),
  funnel as (
    select
      a.qid,
      grouping(a.qid) = 1 as is_total,
      count(distinct a.actor) filter (where a.type = 'view_question')     as visitors,
      count(distinct a.actor) filter (where a.type = 'open_text')         as opened_text,
      count(distinct a.actor) filter (where a.type = 'finish_text')       as finished_text,
      count(distinct a.actor) filter (where a.type = 'ask_ai')            as asked_ai,
      count(distinct a.actor) filter (where a.type = 'submit_reflection') as reflected,
      count(distinct a.actor) filter (where a.type = 'unlock')            as unlocked,
      count(distinct a.actor) filter (where a.type = 'comment')           as commented
    from actors a
    group by grouping sets ((a.qid), ())
  ),
  fb as (
    select
      f.question_id as qid,
      grouping(f.question_id) = 1 as is_total,
      count(*) as n,
      round(avg(f.rating), 2) as rating,
      round(avg(f.ai_helped), 2) as ai_helped,
      round(avg(f.own_view), 2) as own_view
    from public.feedback f
    where f.question_id is not null
    group by grouping sets ((f.question_id), ())
  )
  select
    coalesce(fu.qid, fb.qid),
    coalesce(fu.visitors, 0), coalesce(fu.opened_text, 0), coalesce(fu.finished_text, 0),
    coalesce(fu.asked_ai, 0), coalesce(fu.reflected, 0), coalesce(fu.unlocked, 0),
    coalesce(fu.commented, 0),
    coalesce(fb.n, 0), fb.rating, fb.ai_helped, fb.own_view
  from funnel fu
  full join fb on fb.is_total = fu.is_total and fb.qid is not distinct from fu.qid
  order by coalesce(fu.qid, fb.qid) nulls first;
end;
$$;

grant execute on function public.admin_analytics() to authenticated;


-- =============================================================
-- 0004_rate_limits.sql
-- =============================================================
-- 古問 LORE — rate limits for reports and analytics events
-- Run after 0003_admin_analytics.sql.
--
-- Already limited elsewhere: comments (10 per 10 minutes, 0002_rls.sql),
-- AI Companion (AI_DAILY_LIMIT per day, in the API route), reflections
-- (one per question), reports (one per post per person), sign-in emails
-- (Supabase Auth's own limits).

create index if not exists events_user_recent on public.events (user_id, created_at) where user_id is not null;
create index if not exists events_anon_recent on public.events (anon_id, created_at) where anon_id is not null;
create index if not exists reports_reporter_recent on public.reports (reporter_id, created_at);

-- Reports: at most 20 per person per hour.
create or replace function public.reports_rate_limit()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.uid() is not null and (
    select count(*) from public.reports r
    where r.reporter_id = new.reporter_id and r.created_at > now() - interval '1 hour'
  ) >= 20 then
    raise exception 'Too many reports — please wait a while';
  end if;
  return new;
end;
$$;

create trigger reports_rate_limit
  before insert on public.reports
  for each row execute function public.reports_rate_limit();

-- Events: at most 120 per person (or per signed-out browser) per hour.
-- Extra events are dropped silently so spamming can't inflate the analytics,
-- and a real reader never sees an error.
create or replace function public.events_rate_limit()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  -- Inside SECURITY DEFINER, current_user is this function's owner; the
  -- caller's role (as set by Supabase's API) is in the `role` setting.
  if coalesce(current_setting('role', true), 'none') not in ('anon', 'authenticated') then
    return new; -- service role / SQL editor
  end if;
  if new.user_id is null and new.anon_id is null then
    return null; -- nothing to attribute it to
  end if;
  if (
    select count(*) from public.events e
    where e.created_at > now() - interval '1 hour'
      and ((new.user_id is not null and e.user_id = new.user_id)
        or (new.user_id is null and e.anon_id = new.anon_id))
  ) >= 120 then
    return null;
  end if;
  return new;
end;
$$;

create trigger events_rate_limit
  before insert on public.events
  for each row execute function public.events_rate_limit();


-- =============================================================
-- 0005_stage1_spec_gaps.sql
-- =============================================================
-- 古問 LORE — Stage 1 alignment migration
-- Run after 0004_rate_limits.sql.
--
-- The MVP already had the tables, RLS and analytics described in the brief.
-- This migration adds only the pieces the new brief needs and that were
-- missing, without renaming or rewriting the tested schema:
--
--   * `feedback` is now a valid analytics event type.
--   * `ai_insights.response_count` records the sample size used for a summary.
--   * `ai_usage` exposes the existing `ai_messages_usage` counter under the
--     name used in the brief (a view, so there is still one source of truth).
--   * `excerpts.license_note` can record a licence or rights note.
--   * `question_reflection_count()` lets the locked state show how many
--     reflections are waiting without exposing any of them.
--   * `analytics_summary` exposes the admin-only analytics function as a view.
--
-- Safe to run more than once: columns use IF NOT EXISTS, the event-type
-- constraint is dropped and recreated, functions/views are replaced.

-- ─────────────────────────────────────────────────────────────
-- 1. AI Insight sample size
-- ─────────────────────────────────────────────────────────────

alter table public.ai_insights
  add column if not exists response_count integer not null default 0;

-- Backfill rows generated before this column existed; summary_json->>'total'
-- is written by lib/ai/insight-summary.ts.
update public.ai_insights
set response_count = coalesce((summary_json ->> 'total')::integer, 0)
where response_count = 0;

-- ─────────────────────────────────────────────────────────────
-- 2. `feedback` event type
-- ─────────────────────────────────────────────────────────────
-- Drop whichever CHECK constraint guards events.type (its generated name can
-- differ between projects), then install the complete list.

do $$
declare
  c record;
begin
  for c in
    select conname
    from pg_constraint
    where conrelid = 'public.events'::regclass
      and contype = 'c'
      and pg_get_constraintdef(oid) like '%type%'
  loop
    execute format('alter table public.events drop constraint %I', c.conname);
  end loop;
end $$;

alter table public.events
  add constraint events_type_check check (type in (
    'view_question', 'open_text', 'finish_text', 'ask_ai',
    'submit_reflection', 'unlock', 'comment', 'feedback'));

-- ─────────────────────────────────────────────────────────────
-- 3. Brief-compatible name for the AI usage counter
-- ─────────────────────────────────────────────────────────────
-- security_invoker keeps the table's RLS in force: a reader sees only their
-- own rows, not everybody's usage.

create or replace view public.ai_usage
with (security_invoker = true) as
select id, user_id, question_id, created_at
from public.ai_messages_usage;

-- ─────────────────────────────────────────────────────────────
-- 4. Rights metadata for excerpts
-- ─────────────────────────────────────────────────────────────

alter table public.excerpts
  add column if not exists license_note text;

-- ─────────────────────────────────────────────────────────────
-- 5. Locked-state count
-- ─────────────────────────────────────────────────────────────
-- Only a number is returned. It is safe for signed-out visitors and does not
-- reveal bodies, authors or anything else.

create or replace function public.question_reflection_count(p_question uuid)
returns integer
language sql stable security definer set search_path = ''
as $$
  select count(*)::integer
  from public.reflections r
  where r.question_id = p_question
    and r.status = 'published';
$$;

-- ─────────────────────────────────────────────────────────────
-- 6. Analytics view
-- ─────────────────────────────────────────────────────────────
-- Same rows and columns as admin_analytics(); the function itself refuses
-- anyone who is not an admin.

create or replace view public.analytics_summary
with (security_invoker = true) as
select * from public.admin_analytics();

grant execute on function public.question_reflection_count(uuid) to anon, authenticated;
grant select on public.ai_usage to authenticated;
grant select on public.analytics_summary to authenticated;


-- =============================================================
-- 0006_stage2_7.sql
-- =============================================================
-- 古問 LORE — Stage 2–7 database changes
-- Run after 0005_stage1_spec_gaps.sql.
--
--   * profiles.nickname_chosen — first-time readers choose a nickname.
--   * reflection_feed() now supports LIMIT/OFFSET for pagination.
--   * admin_analytics() accepts a date range.
--   * AI insights can only be written by the service role (the server).
--   * supporting indexes.
--
-- Re-running the nickname backfill marks every existing profile as having
-- chosen a nickname. That is intended for this one-time migration; do not
-- re-run it after real users have signed up.

-- ─────────────────────────────────────────────────────────────
-- 1. First-time nickname
-- ─────────────────────────────────────────────────────────────

alter table public.profiles
  add column if not exists nickname_chosen boolean not null default false;

-- Existing accounts keep their current nickname; new accounts start false.
update public.profiles set nickname_chosen = true where nickname_chosen = false;

-- The 0002 grant only covers nickname and language. The welcome/profile
-- forms also write nickname_chosen, so grant that column explicitly.
grant update (nickname_chosen) on public.profiles to authenticated;

-- ─────────────────────────────────────────────────────────────
-- 2. Paginated reflection feed
-- ─────────────────────────────────────────────────────────────

drop function if exists public.reflection_feed(uuid);

create or replace function public.reflection_feed(
  p_question uuid,
  p_limit integer default 20,
  p_offset integer default 0
)
returns table (
  id             uuid,
  body           text,
  is_anonymous   boolean,
  nickname       text,
  submitted_at   timestamptz,
  like_count     bigint,
  comment_count  bigint,
  liked_by_me    boolean,
  is_mine        boolean
)
language sql stable security definer set search_path = ''
as $$
  select
    r.id,
    r.body,
    r.is_anonymous,
    case when r.is_anonymous then null else p.nickname end,
    r.submitted_at,
    (select count(*) from public.likes l where l.reflection_id = r.id),
    (select count(*) from public.comments c
       where c.reflection_id = r.id and c.status = 'visible'),
    exists (select 1 from public.likes l
              where l.reflection_id = r.id and l.user_id = auth.uid()),
    coalesce(r.user_id = auth.uid(), false)
  from public.reflections r
  join public.profiles p on p.id = r.user_id
  where r.question_id = p_question
    and r.status = 'published'
    and public.has_reflected(p_question)
  order by r.submitted_at desc, r.id
  limit greatest(1, least(coalesce(p_limit, 20), 100))
  offset greatest(0, coalesce(p_offset, 0));
$$;

grant execute on function public.reflection_feed(uuid, integer, integer) to anon, authenticated;

-- ─────────────────────────────────────────────────────────────
-- 3. Admin analytics with a date range
-- ─────────────────────────────────────────────────────────────

drop view if exists public.analytics_summary;
drop function if exists public.admin_analytics();

create or replace function public.admin_analytics(
  p_from timestamptz default null,
  p_to timestamptz default null
)
returns table (
  question_id     uuid,
  visitors        bigint,
  visitors_signed_in bigint,
  opened_text     bigint,
  finished_text   bigint,
  asked_ai        bigint,
  reflected       bigint,
  unlocked        bigint,
  commented       bigint,
  feedback_count  bigint,
  avg_rating      numeric,
  avg_ai_helped   numeric,
  avg_own_view    numeric
)
language plpgsql stable security definer set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;

  return query
  with actors as (
    select e.question_id as qid, e.type,
           coalesce(e.user_id::text, e.anon_id) as actor,
           e.user_id is not null as signed_in
    from public.events e
    where e.question_id is not null
      and coalesce(e.user_id::text, e.anon_id) is not null
      and (p_from is null or e.created_at >= p_from)
      and (p_to is null or e.created_at < p_to)
  ),
  funnel as (
    select
      a.qid,
      grouping(a.qid) = 1 as is_total,
      count(distinct a.actor) filter (where a.type = 'view_question')     as visitors,
      count(distinct a.actor) filter (where a.type = 'view_question' and a.signed_in) as visitors_signed_in,
      count(distinct a.actor) filter (where a.type = 'open_text')         as opened_text,
      count(distinct a.actor) filter (where a.type = 'finish_text')       as finished_text,
      count(distinct a.actor) filter (where a.type = 'ask_ai')            as asked_ai,
      count(distinct a.actor) filter (where a.type = 'submit_reflection') as reflected,
      count(distinct a.actor) filter (where a.type = 'unlock')            as unlocked,
      count(distinct a.actor) filter (where a.type = 'comment')           as commented
    from actors a
    group by grouping sets ((a.qid), ())
  ),
  fb as (
    select
      f.question_id as qid,
      grouping(f.question_id) = 1 as is_total,
      count(*) as n,
      round(avg(f.rating), 2) as rating,
      round(avg(f.ai_helped), 2) as ai_helped,
      round(avg(f.own_view), 2) as own_view
    from public.feedback f
    where f.question_id is not null
      and (p_from is null or f.created_at >= p_from)
      and (p_to is null or f.created_at < p_to)
    group by grouping sets ((f.question_id), ())
  )
  select
    coalesce(fu.qid, fb.qid),
    coalesce(fu.visitors, 0), coalesce(fu.visitors_signed_in, 0),
    coalesce(fu.opened_text, 0), coalesce(fu.finished_text, 0),
    coalesce(fu.asked_ai, 0), coalesce(fu.reflected, 0), coalesce(fu.unlocked, 0),
    coalesce(fu.commented, 0),
    coalesce(fb.n, 0), fb.rating, fb.ai_helped, fb.own_view
  from funnel fu
  full join fb on fb.is_total = fu.is_total and fb.qid is not distinct from fu.qid
  order by coalesce(fu.qid, fb.qid) nulls first;
end;
$$;

grant execute on function public.admin_analytics(timestamptz, timestamptz) to authenticated;

create or replace view public.analytics_summary
with (security_invoker = true) as
select * from public.admin_analytics();

grant select on public.analytics_summary to authenticated;

-- ─────────────────────────────────────────────────────────────
-- 4. AI insights: server-only writes
-- ─────────────────────────────────────────────────────────────

drop policy if exists "admin writes insights" on public.ai_insights;
drop policy if exists "admin deletes insights" on public.ai_insights;
revoke insert, delete on public.ai_insights from authenticated;

-- ─────────────────────────────────────────────────────────────
-- 5. Indexes
-- ─────────────────────────────────────────────────────────────

create index if not exists reflections_feed_order
  on public.reflections (question_id, status, submitted_at desc);
create index if not exists feedback_created_at on public.feedback (created_at);
